#!/usr/bin/env bash
# Runs the `product` step of .github/workflows/ansible_role.yml, as written in the workflow, against fixtures.
#   <name>@<version>[+arc].json  product output, byte for byte, generated by
#                                dagger-container-builds@0.4.1 builds/ansible.ProductJson
#   <name>.dockerfiles[+role|+all].json  dockerfiles output, compared as JSON, with no ansible files,
#                                the role template's (meta/requirements.yml, test.yml), or all four
set -euo pipefail

root=$(cd "$(dirname "$0")/.." && pwd)
fixtures=$root/test/fixtures/ansible_role
step=$(yq '.jobs.product.steps[] | select(.id == "product") | .run' "$root/.github/workflows/ansible_role.yml")
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

pass=0
fail=0

# run_step <config> <version> <arc_hosts> <files: none|role|all>; prints the GITHUB_OUTPUT file path
run_step() {
  local dir=$work/$RANDOM
  mkdir -p "$dir/meta"
  cp "$1" "$dir/config.yaml"
  case "$4" in
    role) touch "$dir/meta/requirements.yml" "$dir/test.yml" ;;
    all) touch "$dir/requirements.yml" "$dir/meta/requirements.yml" "$dir/test.yml" "$dir/playbook.yml" ;;
  esac
  : > "$dir/out"
  (cd "$dir" && CONFIG=config.yaml VERSION=$2 ARC=auto ARC_LABEL=arc-arm64 ARC_HOSTS=$3 GITHUB_OUTPUT=$dir/out \
    bash -c "$step" > /dev/null)
  echo "$dir/out"
}

check() {
  if [ "$2" = "$3" ]; then
    pass=$((pass + 1))
    echo "ok   $1"
  else
    fail=$((fail + 1))
    echo "FAIL $1"
    diff <(printf '%s\n' "$2") <(printf '%s\n' "$3") || true
  fi
}

for expected in "$fixtures"/*@*.json; do
  base=$(basename "$expected" .json)
  name=${base%@*}
  rest=${base#*@}
  version=${rest%+arc}
  arc_hosts=''
  [ "$rest" != "$version" ] && arc_hosts=mac-a
  out=$(run_step "$fixtures/$name.yaml" "$version" "$arc_hosts" none)
  check "product $base" "$(cat "$expected")" "$(sed -n 's/^product=//p' "$out")"
done

for expected in "$fixtures"/*.dockerfiles*.json; do
  base=$(basename "$expected" .json)
  name=${base%.dockerfiles*}
  files=none
  [[ $base == *+role ]] && files=role
  [[ $base == *+all ]] && files=all
  out=$(run_step "$fixtures/$name.yaml" latest '' "$files")
  check "dockerfiles $base" "$(jq -c . "$expected")" "$(sed -n 's/^dockerfiles=//p' "$out" | jq -c .)"
done

echo "$pass passed, $fail failed"
[ "$fail" -eq 0 ]
